from rdkit import Chem
import numpy as np
m=Chem.MolFromMolFile('/tmp/copper.mol',sanitize=False,removeHs=False)
print(Chem.MolToSmiles(m))
xyz=np.array(m.GetConformer().GetPositions());
for j in [0,15,33]:print(j,'Cu dist',np.linalg.norm(xyz[34]-xyz[j]))
for a,b in [(0,15),(0,33),(15,33)]:
 v,w=xyz[a]-xyz[34],xyz[b]-xyz[34];print(a,b,'angle',np.degrees(np.arccos(np.dot(v,w)/np.linalg.norm(v)/np.linalg.norm(w))))
with open('initial.xyz','w') as f:
 f.write(f'{m.GetNumAtoms()}\nBis(NHC)-pyridine copper(I) cation; initial RDKit ETKDG\n')
 for a,p in zip(m.GetAtoms(),xyz):f.write('%s %.8f %.8f %.8f\n'%(a.GetSymbol(),*p))
